   if grid[r][c]!=val or (r,c) in seen: continue
   q=[(r,c)];seen.add((r,c)); cells=[]
   while q:
    x,y=q.pop();cells.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     z=(x+dx,y+dy)
     if 0<=z[0]<R and 0<=z[1]<C and grid[z[0]][z[1]]==val and z not in seen:seen.add(z);q.append(z)
   out.append(cells)
 return out
